final class SymbolTableLayoutTests: XCTestCase {
    private func line(_ text: String, _ x: CGFloat, _ y: CGFloat, _ width: CGFloat = 0.12) -> OCRLayoutLine {
        OCRLayoutLine(text: text, bounds: CGRect(x: x, y: y, width: width, height: 0.025))
    }
    private func table(context: String = "弊社で発行しているパスワードは以下の文字種をランダムに組み合わせた8桁です。") -> [OCRLayoutLine] {
        [line("ログインできない場合、パスワードを確認", 0.02, 0.83, 0.9),
         line(context, 0.02, 0.76, 0.9),
         line("小文字", 0.06, 0.65), line("abcdefghijklmnopqrstuvwxyz", 0.25, 0.65, 0.6),
         line("大文字", 0.06, 0.59), line("ABCDEFGHIJKLMNOPQRSTUVWXYZ", 0.25, 0.59, 0.65),
         line("数字", 0.08, 0.53), line("123456789", 0.25, 0.53, 0.3),
         line("記号", 0.08, 0.47), line(".!_/`()[]+-=$#&@~", 0.25, 0.47, 0.4),
         line("パソコンでの入力方法", 0.02, 0.3, 0.6),
         line("記号", 0.02, 0.2), line("名称", 0.15, 0.2), line("入力するキー", 0.4, 0.2, 0.4)]
    }
    func testSelectsOnlySymbolValueAndIgnoresUnrelatedNegativeProse() throws {
        let regions = SymbolTableLocator.regions(in: table())
        XCTAssertEqual(regions.count, 1)
        let region = try XCTUnwrap(regions.first)
        XCTAssertEqual(region.primary, [".!_/`()[]+-=$#&@~"])
        XCTAssertEqual(region.bounds.minX, 0.25, accuracy: 0.001)
        XCTAssertFalse(region.evidence.contains("ログインできない"))
        XCTAssertFalse(region.evidence.contains("入力するキー"))
        XCTAssertTrue(SymbolEvidenceValidator.accepts(region.evidence, source: .characterTable))
    }
    func testIndependentTablesAreNotMergedAndSplitCellsCanBeRead() {
        let other = table().map { OCRLayoutLine(text: $0.text, bounds: $0.bounds.offsetBy(dx: 0, dy: -0.4)) }
        XCTAssertEqual(SymbolTableLocator.regions(in: table() + other).count, 2)
        var split = table().filter { $0.text != ".!_/`()[]+-=$#&@~" }
        split += [line("!@#", 0.25, 0.47, 0.15), line("[]{}", 0.42, 0.47, 0.15)]
        XCTAssertEqual(SymbolTableLocator.regions(in: split).first?.primary, ["!@#", "[]{}"])
    }
    func testRejectsForbiddenContextAndUnrelatedSymbolTable() {
        XCTAssertTrue(SymbolTableLocator.regions(in: table(context: "パスワードは以下の文字種を使用不可です。")).isEmpty)
        XCTAssertTrue(SymbolTableLocator.regions(in: table(context: "記号の入力するキーと名称の例です。")).isEmpty)
        XCTAssertTrue(SymbolTableLocator.regions(in: table().filter { !["小文字", "大文字", "数字"].contains($0.text) }).isEmpty)
        XCTAssertTrue(SymbolEvidenceValidator.visualCandidate(symbols: "!", permission: "記号の入力方法", explicit: true, source: .characterTable).isEmpty)
    }
    func testRejectsWrongColumnAndWrongRowAlignment() {
        let wrong = table().map { $0.text == ".!_/`()[]+-=$#&@~" ? line($0.text, 0.7, 0.47, 0.2) : $0 }
        XCTAssertTrue(SymbolTableLocator.regions(in: wrong).isEmpty)
        let below = table().map { $0.text == ".!_/`()[]+-=$#&@~" ? line($0.text, 0.25, 0.4, 0.4) : $0 }
        XCTAssertTrue(SymbolTableLocator.regions(in: below).isEmpty)
    }
}

final class SymbolListLayoutTests: XCTestCase {
    private func line(_ text: String, _ x: CGFloat, _ y: CGFloat, _ width: CGFloat = 0.4) -> OCRLayoutLine {
        OCRLayoutLine(text: text, bounds: CGRect(x: x, y: y, width: width, height: 0.03))
    }
    func testStandaloneAndWrappedListsNeedNoPermissionStatement() throws {
        let regions = SymbolListLocator.regions(in: [line("!@#$", 0.1, 0.6), line("[]{}~", 0.1, 0.55)])
        XCTAssertEqual(regions.count, 1)
        let region = try XCTUnwrap(regions.first)
        XCTAssertEqual(Set(region.primary.joined()), Set("!@#$[]{}~"))
        XCTAssertTrue(SymbolEvidenceValidator.accepts(region.evidence, source: .symbolList))
        XCTAssertFalse(SymbolEvidenceValidator.isPermission(region.evidence))
    }
    func testInterveningProseAndResourceLimitsPreventJoining() {
        let parts = [line("!@#$", 0.1, 0.6, 0.1), line("[]{}", 0.25, 0.6, 0.1)]
        XCTAssertEqual(SymbolListLocator.regions(in: parts).count, 1)
        XCTAssertEqual(SymbolListLocator.regions(in: parts + [line("説明", 0.205, 0.6, 0.04)]).count, 2)
        XCTAssertEqual(SymbolListLocator.regions(in: [line("!@#$", 0.1, 0.6, 0.1), line("[]{}", 0.6, 0.6, 0.1)]).count, 2)
        XCTAssertTrue(SymbolListLocator.regions(in: Array(repeating: parts[0], count: 97)).isEmpty)
        XCTAssertTrue(SymbolListLocator.regions(in: parts + Array(repeating: line("説明", 0.1, 0.9), count: 511)).isEmpty)
    }
    func testModelCandidatesRespectSourceAndDoNotGuessConfusedGlyphs() {
        XCTAssertEqual(Set(SymbolEvidenceValidator.visualCandidate(symbols: "！＃＄％", permission: "!#$%", explicit: true, source: .symbolList)), Set("!#$%"))
        XCTAssertTrue(SymbolEvidenceValidator.visualCandidate(symbols: "!#$%", permission: "無関係な文章", explicit: true, source: .symbolList).isEmpty)
        XCTAssertTrue(SymbolEvidenceValidator.visualCandidate(symbols: "!#$%", permission: "!#$%", explicit: false, source: .symbolList).isEmpty)
        XCTAssertTrue(SymbolEvidenceValidator.visualCandidate(symbols: "!#$%口", permission: "!#$%", explicit: true, source: .symbolList).isEmpty)
        XCTAssertTrue(ScreenshotImporter.isSymbolFragment("口"))
        XCTAssertTrue(SymbolEvidenceValidator.mergedOCRCandidate(primary: ["口①"], reread: []).isEmpty)
    }
    func testURLProseMasksAndDecorativeRulesAreNotLists() {
        for text in ["https://example.com/path?a=1", "https://a.b/?!#$%&", "www.x.y/?!#$%&", "a+b@x.io?!#$%", "foo@example.com", "名前（例）を入力。", "********", "------", "••••••"] {
            XCTAssertTrue(SymbolListLocator.regions(in: [line(text, 0.1, 0.6)]).isEmpty, text)
        }
    }
    func testForbiddenAndTypingExamplesAreExcluded() {
        XCTAssertTrue(SymbolListLocator.regions(in: [line("使用不可", 0.1, 0.66), line("!@#$%", 0.1, 0.6)]).isEmpty)
        XCTAssertTrue(SymbolListLocator.regions(in: [line("使用禁止", 0.01, 0.6, 0.08), line("!@#$%", 0.1, 0.6)]).isEmpty)
        XCTAssertTrue(SymbolListLocator.regions(in: [line("入力するキー", 0.1, 0.66), line("!@#$%", 0.1, 0.6)]).isEmpty)
        XCTAssertTrue(SymbolListLocator.regions(in: [line("パスワードに以下の文字種は使用不可", 0.1, 0.82, 0.8), line("!@#$%", 0.1, 0.6)]).isEmpty)
    }
    func testDistantListsRemainIndependentAndSplitCellsCanJoin() {
        XCTAssertEqual(SymbolListLocator.regions(in: [line("!@#$%", 0.1, 0.8), line("[]{}~", 0.1, 0.3)]).count, 2)
        let cells = [line("!@", 0.1, 0.6, 0.1), line("#$%", 0.22, 0.6, 0.1)]
        XCTAssertEqual(SymbolListLocator.regions(in: cells).count, 1)
    }
}

private actor ImportAnalysisGate {
    private var continuations: [CheckedContinuation<ScreenshotAnalysis, Never>] = []
    var count: Int { continuations.count }
    func analyze(_ data: Data) async -> ScreenshotAnalysis {
        await withCheckedContinuation { continuations.append($0) }
    }
    func finish(_ index: Int, symbols: String) {
        continuations[index].resume(returning: ScreenshotAnalysis(recognizedText: symbols, proposedSymbols: symbols, evidence: "Allowed symbols:", note: "test"))
    }
}

@MainActor final class ScreenshotImportLifecycleTests: XCTestCase {
    private func waitUntil(_ predicate: () async -> Bool) async throws {
        for _ in 0..<200 { if await predicate() { return }; try await Task.sleep(for: .milliseconds(10)) }
        XCTFail("Import state did not settle")
    }
    func testCompletedReviewAndManualEditsSurviveBackground() async throws {
        let session = ScreenshotImportSession { _ in ScreenshotAnalysis(recognizedText: "fixture", proposedSymbols: "!{#", evidence: "Allowed symbols:", note: "test") }
        session.start { Data([1]) }
        try await waitUntil { !session.loading }
        session.candidate = "!{"
        session.suspend(); session.resume()
        XCTAssertEqual(session.analysis?.recognizedText, "fixture")
        XCTAssertEqual(session.candidate, "!{"); XCTAssertFalse(session.loading)
        session.clear()
        XCTAssertNil(session.analysis); XCTAssertEqual(session.candidate, "")
    }
    func testBackgroundResumesWorkAndRejectsLateCancelledResult() async throws {
        let gate = ImportAnalysisGate()
        let session = ScreenshotImportSession { await gate.analyze($0) }
        session.start { Data([1]) }
        try await waitUntil { await gate.count == 1 }
        session.suspend()
        XCTAssertFalse(session.loading); XCTAssertTrue(session.suspended)
        session.resume()
        try await waitUntil { await gate.count == 2 }
        await gate.finish(1, symbols: "!{")
        try await waitUntil { !session.loading }
        await gate.finish(0, symbols: "#")
        try await Task.sleep(for: .milliseconds(30))
        XCTAssertEqual(session.candidate, "!{")
        XCTAssertFalse(session.suspended); XCTAssertNil(session.errorMessage)
    }
    func testClosingEditorDiscardsPendingResult() async throws {
        let gate = ImportAnalysisGate()
        let session = ScreenshotImportSession { await gate.analyze($0) }
        session.start { Data([1]) }
        try await waitUntil { await gate.count == 1 }
        session.clear()
        await gate.finish(0, symbols: "!{")
        try await Task.sleep(for: .milliseconds(30))
        XCTAssertNil(session.analysis); XCTAssertEqual(session.candidate, "")
        XCTAssertFalse(session.loading); XCTAssertFalse(session.suspended)
    }
    func testReplacingImageRejectsOldResultAndRecoversAfterFailure() async throws {
        let gate = ImportAnalysisGate()
        let session = ScreenshotImportSession { await gate.analyze($0) }
        session.start { Data([1]) }
        try await waitUntil { await gate.count == 1 }
        session.start { Data([2]) }
        try await waitUntil { await gate.count == 2 }
        await gate.finish(0, symbols: "#")
        try await Task.sleep(for: .milliseconds(30))
        XCTAssertTrue(session.loading); XCTAssertNil(session.analysis)
        await gate.finish(1, symbols: "!{")
        try await waitUntil { !session.loading }
        XCTAssertEqual(session.candidate, "!{")
        session.start { throw ScreenshotImportError.invalidImage }
        try await waitUntil { !session.loading }
        XCTAssertNotNil(session.errorMessage)
        session.start { Data([3]) }
        try await waitUntil { await gate.count == 3 }
        XCTAssertNil(session.errorMessage)
        await gate.finish(2, symbols: "{}")
        try await waitUntil { !session.loading }
        XCTAssertEqual(session.candidate, "{}")
    }
}

@MainActor final class CaptureRecoveryTests: XCTestCase {
    func testUIKitCaptureTraitAndRestorationPreserveUserVisibilityChoice() async throws {
        let protection = ScreenProtectionState()
        let view = CaptureStatusView(frame: .zero)
        view.onChange = protection.update
        let scene = try XCTUnwrap(UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }.first)
        let previous = scene.windows.first { $0.isKeyWindow }
        let window = UIWindow(windowScene: scene)
        let controller = UIViewController(); controller.view = view; window.rootViewController = controller
        window.makeKeyAndVisible()
        defer { window.isHidden = true; previous?.makeKey() }
        window.traitOverrides.sceneCaptureState = .active
        try await Task.sleep(for: .milliseconds(20)); view.refresh()
        XCTAssertTrue(protection.isCaptured); XCTAssertFalse(protection.allowsSecret(revealed: true))
        window.traitOverrides.sceneCaptureState = .inactive
        try await Task.sleep(for: .milliseconds(20)); view.refresh()
        XCTAssertFalse(protection.isCaptured); XCTAssertTrue(protection.allowsSecret(revealed: true))
        XCTAssertFalse(protection.allowsSecret(revealed: false))
    }
}

@MainActor final class PrivacyCoverTests: XCTestCase {
    private struct Harness: View {
        @Bindable var model: GeneratorModel
        let phase: ScenePhase
        var body: some View {
            Color.red.ignoresSafeArea()
                .sensitiveScene(enabled: model.security.protectAppSwitcher)
                .environment(\.scenePhase, phase)
        }
    }
    func testEntireCoverFollowsPreferenceWhileInactiveAndInBackground() async throws {
        let scene = try XCTUnwrap(UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }.first)
        let previous = scene.windows.first { $0.isKeyWindow }
        let window = UIWindow(windowScene: scene)
        window.overrideUserInterfaceStyle = .light
        let model = GeneratorModel()
        let controller = UIHostingController(rootView: Harness(model: model, phase: .active))
        window.rootViewController = controller; window.makeKeyAndVisible()
        defer { window.isHidden = true; previous?.makeKey() }
        for phase in [ScenePhase.active, .inactive, .background, .active] {
            controller.rootView = Harness(model: model, phase: phase)
            for enabled in [true, false, true] {
                model.security.protectAppSwitcher = enabled
                try await Task.sleep(for: .milliseconds(40))
                controller.view.layoutIfNeeded()
                let rendered = UIGraphicsImageRenderer(bounds: controller.view.bounds).image { _ in
                    controller.view.drawHierarchy(in: controller.view.bounds, afterScreenUpdates: true)
                }
                let sample = try XCTUnwrap(rendered.cgImage?.cropping(to: CGRect(x: 20, y: 20, width: 1, height: 1)))
                var pixel = [UInt8](repeating: 0, count: 4)
                try pixel.withUnsafeMutableBytes { buffer in
                    let context = try XCTUnwrap(CGContext(data: buffer.baseAddress, width: 1, height: 1,
                        bitsPerComponent: 8, bytesPerRow: 4, space: CGColorSpaceCreateDeviceRGB(),
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue | CGBitmapInfo.byteOrder32Big.rawValue))
                    context.draw(sample, in: CGRect(x: 0, y: 0, width: 1, height: 1))
                }
                if enabled && phase != .active {
                    XCTAssertGreaterThan(pixel[1], 220); XCTAssertGreaterThan(pixel[2], 220)
                } else {
                    XCTAssertLessThan(pixel[1], 120); XCTAssertLessThan(pixel[2], 120)
                }
                if phase == .inactive {
                    let image = XCTAttachment(image: rendered)
                    image.name = enabled ? "Inactive cover on" : "Inactive cover off"
                    image.lifetime = .keepAlways; add(image)
                }
                XCTAssertTrue(model.security.protectCapture)
            }
        }
    }
}

@MainActor final class GeneratorLifecycleTests: XCTestCase {
    func testSettingsAndRevealPreferenceSurviveNewModelButSecretsDoNot() async throws {
        let suite = "passgen.tests.\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let first = GeneratorModel(preferences: defaults)
        first.recipe.lengthText = "４８"; first.recipe.countText = "2"
        first.recipe.uppercaseCharacters = "AZ"; first.recipe.similarExclusions = "O0"
        first.recipe.noAdjacent = true; first.recipe.words = 9; first.recipe.separator = "_"
        first.revealed = true
        first.security.allowUniversalClipboard = true; first.security.clipboardSeconds = 90
        first.security.protectCapture = false
        first.generateOrStop()
        for _ in 0..<100 {
            if !first.busy { break }
            try await Task.sleep(for: .milliseconds(5))
        }
        let restored = GeneratorModel(preferences: defaults)
        XCTAssertEqual(restored.recipe.length, 48); XCTAssertEqual(restored.recipe.count, 2)
        XCTAssertEqual(restored.recipe.uppercaseCharacters, "AZ")
        XCTAssertEqual(restored.recipe.similarExclusions, "O0"); XCTAssertTrue(restored.recipe.noAdjacent)
        XCTAssertEqual(restored.recipe.words, 9); XCTAssertEqual(restored.recipe.separator, "_")
        XCTAssertTrue(restored.revealed); XCTAssertTrue(restored.results.isEmpty)
        let data = defaults.data(forKey: "generation.preferences.v1")!
        let object = try JSONSerialization.jsonObject(with: data) as! [String: Any]
        XCTAssertEqual(Set(object.keys), ["version", "recipe", "revealed", "security"])
        XCTAssertTrue(restored.security.allowUniversalClipboard); XCTAssertEqual(restored.security.clipboardSeconds, 90)
        XCTAssertFalse(restored.security.protectCapture)
        restored.chooseMode(.passphrase); restored.chooseMode(.password)
        XCTAssertEqual(restored.recipe.length, 48)
    }

    func testLegacyBackgroundClipboardFlagDoesNotResetPreferences() throws {
        let suite = "passgen.tests.\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let first = GeneratorModel(preferences: defaults)
        first.recipe.lengthText = "48"; first.revealed = true
        first.security.clipboardSeconds = 90; first.security.allowUniversalClipboard = true
        first.security.protectCapture = false; first.security.autoClearClipboard = false
        var object = try JSONSerialization.jsonObject(with: defaults.data(forKey: "generation.preferences.v1")!) as! [String: Any]
        var security = object["security"] as! [String: Any]
        security["clearClipboardOnBackground"] = true
        security.removeValue(forKey: "protectAppSwitcher")
        object["security"] = security
        defaults.set(try JSONSerialization.data(withJSONObject: object), forKey: "generation.preferences.v1")
        let restored = GeneratorModel(preferences: defaults)
        XCTAssertEqual(restored.recipe.length, 48); XCTAssertTrue(restored.revealed)
        XCTAssertEqual(restored.security.clipboardSeconds, 90); XCTAssertTrue(restored.security.allowUniversalClipboard)
        XCTAssertFalse(restored.security.protectCapture); XCTAssertFalse(restored.security.autoClearClipboard)
        XCTAssertTrue(restored.security.protectAppSwitcher)
        restored.recipe.lengthText = "49"
        let saved = try JSONSerialization.jsonObject(with: defaults.data(forKey: "generation.preferences.v1")!) as! [String: Any]
        XCTAssertNil((saved["security"] as! [String: Any])["clearClipboardOnBackground"])
    }

    func testAppSwitcherPreferenceSurvivesReloadWithoutChangingCaptureProtection() {
        let suite = "passgen.tests.\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let first = GeneratorModel(preferences: defaults)
        XCTAssertTrue(first.security.protectAppSwitcher)
        first.recipe.lengthText = "48"; first.security.clipboardSeconds = 90
        first.security.protectAppSwitcher = false
        let restored = GeneratorModel(preferences: defaults)
        XCTAssertFalse(restored.security.protectAppSwitcher); XCTAssertTrue(restored.security.protectCapture)
        XCTAssertEqual(restored.recipe.length, 48); XCTAssertEqual(restored.security.clipboardSeconds, 90)
        let capture = ScreenProtectionState(); capture.update(true)
        XCTAssertFalse(capture.allowsSecret(revealed: true, protectCapture: restored.security.protectCapture))
        restored.security.protectCapture = false; restored.security.protectAppSwitcher = true
        let reloaded = GeneratorModel(preferences: defaults)
        XCTAssertTrue(reloaded.security.protectAppSwitcher); XCTAssertFalse(reloaded.security.protectCapture)
    }

    func testRevealPreferenceSurvivesRegenerationAndBackground() async throws {
        let model = GeneratorModel(); model.revealed = true
        for _ in 0..<2 {
            model.generateOrStop()
            for _ in 0..<100 {
                if !model.busy { break }
                try await Task.sleep(for: .milliseconds(5))
            }
            XCTAssertTrue(model.revealed)
        }
        model.clear(); XCTAssertTrue(model.revealed)
        model.background(); XCTAssertTrue(model.revealed); XCTAssertTrue(model.results.isEmpty)
    }

    func testCopiedMarksArePerRowAndExpireWithResults() async throws {
        let model = GeneratorModel(); model.recipe.countText = "2"; model.generateOrStop()
        for _ in 0..<100 { if !model.busy { break }; try await Task.sleep(for: .milliseconds(5)) }
        model.copiedIDs.insert(0); model.copiedIDs.insert(1)
        XCTAssertEqual(model.copiedIDs, [0, 1])
        model.generateOrStop(); XCTAssertTrue(model.copiedIDs.isEmpty)
        model.background(); XCTAssertTrue(model.copiedIDs.isEmpty)
    }

    func testClipboardExpiresAtConfiguredTime() async throws {
        let clipboard = SecureClipboard()
        var settings = SecuritySettings(); settings.clipboardSeconds = 5
        clipboard.copy("fake-test-only", settings: settings)
        XCTAssertTrue(UIPasteboard.general.hasStrings)
        try await Task.sleep(for: .seconds(6))
        XCTAssertFalse(UIPasteboard.general.hasStrings)
    }

    func testInvalidPreferencesFallBackWithoutCrashing() {
        let suite = "passgen.tests.\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        defaults.set(Data("invalid".utf8), forKey: "generation.preferences.v1")
        XCTAssertEqual(GeneratorModel(preferences: defaults).recipe.length, 24)
        defaults.set(Data("{\"version\":999}".utf8), forKey: "generation.preferences.v1")
        XCTAssertFalse(GeneratorModel(preferences: defaults).revealed)
    }
    func testNoGenerationOnLaunchAndExplicitGenerateWorks() async throws {
        let model = GeneratorModel()
        XCTAssertTrue(model.results.isEmpty)
        model.generateOrStop()
        for _ in 0..<100 {
            if !model.busy { break }
            try await Task.sleep(for: .milliseconds(20))
        }
        XCTAssertEqual(model.results.count, 1)
        XCTAssertEqual(model.results.first?.value.count, 24)
        XCTAssertFalse(model.revealed)
    }
    func testBackgroundCancelsAndLateResultsNeverReappear() async throws {
        let model = GeneratorModel()
        model.recipe.lengthText = "999999"; model.recipe.countText = "10"
        model.generateOrStop(); model.background()
        try await Task.sleep(for: .milliseconds(100))
        XCTAssertTrue(model.results.isEmpty); XCTAssertFalse(model.busy); XCTAssertFalse(model.revealed)
    }
    func testClipboardDoesNotEraseReplacement() {
        let clipboard = SecureClipboard()
        clipboard.copy("test-only-fake-value")
        UIPasteboard.general.string = "replacement"
        clipboard.clearOwned()
        XCTAssertEqual(UIPasteboard.general.string, "replacement")
        UIPasteboard.general.items = []
    }

    func testIndividualSelectionReachesSharedGenerator() async throws {
        let model = GeneratorModel()
        model.recipe.uppercaseCharacters = "AZ"
        model.recipe.lowercase = false; model.recipe.digits = false; model.recipe.symbolsEnabled = false
        model.generateOrStop()
        for _ in 0..<100 {
            if !model.busy { break }
            try await Task.sleep(for: .milliseconds(5))
        }
        XCTAssertEqual(model.results.count, 1)
        XCTAssertTrue(model.results.first?.value.allSatisfy { "AZ".contains($0) } == true)
    }

    func testStopPreservesCompletedResults() async throws {
        let model = GeneratorModel()
        model.recipe.lengthText = "999999"; model.recipe.countText = "10"
        model.generateOrStop()
        for _ in 0..<200 {
            if !model.results.isEmpty { break }
            try await Task.sleep(for: .milliseconds(2))
        }
        XCTAssertFalse(model.results.isEmpty)
        XCTAssertTrue(model.busy)
        model.generateOrStop()
        for _ in 0..<100 {
            if !model.busy { break }
            try await Task.sleep(for: .milliseconds(5))
        }
        XCTAssertFalse(model.busy)
        XCTAssertFalse(model.results.isEmpty)
        XCTAssertLessThan(model.results.count, model.goal)
